class Curve {
	keys = [];
	type = CURVE_SMOOTHSTEP;
	tension = 0.5;
	_eval = new CurveEvaluator(this);
	constructor(data) {
		if (data) {
			for (let i = 0; i < data.length - 1; i += 2) {
				this.keys.push([data[i], data[i + 1]]);
			}
		}
		this.sort();
	}
	get length() {
		return this.keys.length;
	}
	add(time, value) {
		const keys = this.keys;
		const len = keys.length;
		let i = 0;
		for (; i < len; i++) {
			if (keys[i][0] > time) {
				break;
			}
		}
		const key = [time, value];
		this.keys.splice(i, 0, key);
		return key;
	}
	get(index) {
		return this.keys[index];
	}
	sort() {
		this.keys.sort((a, b) => a[0] - b[0]);
	}
	value(time) {
		return this._eval.evaluate(time, true);
	}
	closest(time) {
		const keys = this.keys;
		const length = keys.length;
		let min = 2;
		let result = null;
		for (let i = 0; i < length; i++) {
			const diff = Math.abs(time - keys[i][0]);
			if (min >= diff) {
				min = diff;
				result = keys[i];
			} else {
				break;
			}
		}
		return result;
	}
	clone() {
		const result = new this.constructor();
		result.keys = this.keys.map((key) => [...key]);
		result.type = this.type;
		result.tension = this.tension;
		return result;
	}
	quantize(precision) {
		precision = Math.max(precision, 2);
		const values = new Float32Array(precision);
		const step = 1 / (precision - 1);
		values[0] = this._eval.evaluate(0, true);
		for (let i = 1; i < precision; i++) {
			values[i] = this._eval.evaluate(step * i);
		}
		return values;
	}
	quantizeClamped(precision, min, max) {
		const result = this.quantize(precision);
		for (let i = 0; i < result.length; ++i) {
			result[i] = Math.min(max, Math.max(min, result[i]));
		}
		return result;
	}
}

class CurveSet {
	curves = [];
	_type = CURVE_SMOOTHSTEP;
	constructor(...args) {
		if (args.length > 1) {
			for (let i = 0; i < args.length; i++) {
				this.curves.push(new Curve(args[i]));
			}
		} else if (args.length === 0) {
			this.curves.push(new Curve());
		} else {
			const arg = args[0];
			if (typeof arg === "number") {
				for (let i = 0; i < arg; i++) {
					this.curves.push(new Curve());
				}
			} else {
				for (let i = 0; i < arg.length; i++) {
					this.curves.push(new Curve(arg[i]));
				}
			}
		}
	}
	get length() {
		return this.curves.length;
	}
	set type(value) {
		this._type = value;
		for (let i = 0; i < this.curves.length; i++) {
			this.curves[i].type = value;
		}
	}
	get type() {
		return this._type;
	}
	get(index) {
		return this.curves[index];
	}
	value(time, result = []) {
		const length = this.curves.length;
		result.length = length;
		for (let i = 0; i < length; i++) {
			result[i] = this.curves[i].value(time);
		}
		return result;
	}
	clone() {
		const result = new this.constructor();
		result.curves = [];
		for (let i = 0; i < this.curves.length; i++) {
			result.curves.push(this.curves[i].clone());
		}
		result._type = this._type;
		return result;
	}
	quantize(precision) {
		precision = Math.max(precision, 2);
		const numCurves = this.curves.length;
		const values = new Float32Array(precision * numCurves);
		const step = 1 / (precision - 1);
		for (let c = 0; c < numCurves; c++) {
			const ev = new CurveEvaluator(this.curves[c]);
			for (let i = 0; i < precision; i++) {
				values[i * numCurves + c] = ev.evaluate(step * i);
			}
		}
		return values;
	}
	quantizeClamped(precision, min, max) {
		const result = this.quantize(precision);
		for (let i = 0; i < result.length; ++i) {
			result[i] = Math.min(max, Math.max(min, result[i]));
		}
		return result;
	}
}

const floatView = new Float32Array(1);
const int32View = new Int32Array(floatView.buffer);
class FloatPacking {
	static float2Half(value) {
		floatView[0] = value;
		const x = int32View[0];
		let bits = x >> 16 & 32768;
		let m = x >> 12 & 2047;
		const e = x >> 23 & 255;
		if (e < 103) {
			return bits;
		}
		if (e > 142) {
			bits |= 31744;
			bits |= (e === 255 ? 0 : 1) && x & 8388607;
			return bits;
		}
		if (e < 113) {
			m |= 2048;
			bits |= (m >> 114 - e) + (m >> 113 - e & 1);
			return bits;
		}
		bits |= e - 112 << 10 | m >> 1;
		bits += m & 1;
		return bits;
	}
	static float2RGBA8(value, data) {
		floatView[0] = value;
		const intBits = int32View[0];
		data.r = (intBits >> 24 & 255) / 255;
		data.g = (intBits >> 16 & 255) / 255;
		data.b = (intBits >> 8 & 255) / 255;
		data.a = (intBits & 255) / 255;
	}
}

class Kernel {
	static concentric(numRings, numPoints) {
		const kernel = [];
		kernel.push(0, 0);
		const spacing = 2 * Math.PI / numRings / numPoints;
		for (let ring = 1; ring <= numRings; ring++) {
			const radius = ring / numRings;
			const circumference = 2 * Math.PI * radius;
			const pointsPerRing = Math.max(1, Math.floor(circumference / spacing));
			const angleStep = 2 * Math.PI / pointsPerRing;
			for (let point = 0; point < pointsPerRing; point++) {
				const angle = point * angleStep;
				const x = radius * Math.cos(angle);
				const y = radius * Math.sin(angle);
				kernel.push(x, y);
			}
		}
		return kernel;
	}
}

